package main

import (
	"bufio"
	"fmt"
	"os"
)

type Scan struct {
	buffer []string
	reader *bufio.Reader
}

func NewScan() *Scan {
	return &Scan{
		buffer: make([]string, 0),
		reader: bufio.NewReader(os.Stdin),
	}
}

func (s *Scan) next() string {
	for {
		if len(s.buffer) > 0 {
			token := s.buffer[0]
			s.buffer = s.buffer[1:]
			return token
		}
		line, err := s.reader.ReadString('\n')
		if err != nil {
			panic("Fail to read")
		}
		start := 0
		s.buffer = s.buffer[:0]
		for i := 0; i <= len(line); i++ {
			if i == len(line) || line[i] == ' ' || line[i] == '\t' || line[i] == '\n' || line[i] == '\r' {
				if start < i {
					s.buffer = append(s.buffer, line[start:i])
				}
				start = i + 1
			}
		}
	}
}

func main() {
	scan := NewScan()
	var n, m int
	fmt.Sscan(scan.next(), &n)
	fmt.Sscan(scan.next(), &m)

	limit := n
	if m > limit {
		limit = m
	}

	res := 0
	for i := 0; i <= limit; i++ {
		for j := 0; j <= limit; j++ {
			if i*i+j == n && i+j*j == m {
				res++
			}
		}
	}
	fmt.Println(res)
}

